import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t}from"./chunks/image-005.C-lrs2Ft.js";import{_ as o,o as _,c as n,a3 as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/60-和亲第四十八.md","filePath":"books/yan-tie-lun/60-和亲第四十八.md","lastUpdated":1784092560000}'),i={name:"books/yan-tie-lun/60-和亲第四十八.md"};function l(e,a,r,m,c,d){return _(),n("div",null,[...a[0]||(a[0]=[s('<p>和亲第四十八 【题解】</p><p>本篇以“和亲”为题，但所论不局限于“和亲”，而是汉家对匈奴的政策。大夫认为，对匈奴决不能放弃军事防备而侈谈仁义，因为匈奴是从来不讲信用的禽兽之国，屡和屡叛，反复无常，这是他们不可改变的自然天性。文学不赞成汉武帝征讨匈奴的决策，认为汉家伐胡几十年来，边境民众因受战争影响而无法过上和平生活。他希望汉家像公刘、太王、周公一样对戎狄致力于仁德教化。双方的分歧仍然体现在现实主义与理想主义之上。</p><p>大夫曰：“昔徐偃王行义而灭，鲁哀公好儒而削[(1)]。知文而不知武，知一而不知二。故君子笃仁以行，然必筑城以自守，设械以自备，为不仁者之害己也。是以古者，蒐狝振旅而数军实焉[(2)]，恐民之愉佚而亡戒难[(3)]。故兵革者国之用，城垒者国之固也；而欲罢之，是去表见里[(4)]，示匈奴心腹也。匈奴轻举潜进，以袭空虚，是犹不介而当矢石之蹊[(5)]，祸必不振[(6)]。此边境之所惧，而有司之所忧也。”</p><p>【注释】</p><p>[(1)]昔徐偃王行义而灭，鲁哀公好儒而削：原作“昔徐偃行王义而灭，好儒而削”，据王利器说校改。徐偃王，徐国君主。关于徐偃王行仁义而亡的故事，先秦两汉古籍多有论及，但彼此说法差异很大。《淮南子·人间训》：“徐偃王为义而亡。”鲁哀公，姬姓，名蒋，为鲁国第二十六任君主。在任期间，鲁国权力掌握在三桓手中。《礼记》和《大戴礼记》中记载了鲁哀公与孔子的几次谈话，被人视为鲁哀公“好儒”的证据。《淮南子·人间训》：“哀公好儒而灭。”</p><p>[(2)]蒐（sōu）狝（xiǎn）振旅而数军实：《左传·隐公五年》：“故春蒐、夏苗、秋狝、冬狩，皆于农隙以讲事也。三年而治兵，入而振旅，归而饮至，以数军实。”杜预注：“蒐，索，择取不孕者。狝，杀也，以杀为名，顺秋气也。振，整也。旅，众也。饮于庙，以数车徒器械及所获也。”春天打猎叫蒐，秋天打猎叫狝。振旅，整治军队。数军实，统计军队的器械、人员、粮饷及俘获物。</p><p>[(3)]佚：通“逸”。愉（tōu）：苟且偷安。亡戒难：忘记戒备灾难。亡，通“忘”。</p><p>[(4)]见：同“现”。</p><p>[(5)]介：通“甲”。石：矢弩，一说，发石。蹊（xī）：路径。</p><p>[(6)]振：救。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“从前徐偃王施行仁义而灭亡，鲁哀公好儒生而公室削弱。他们只知文治而不知武功，只知一个方面而不知两个方面。因此君子厚于仁爱来行事，但一定要修筑城墙来自我守卫，设置器械来自我防备，为的是防止不仁的人坑害自己。所以在古代，春秋打猎，整顿军队，检查车马士卒器械，怕的是民众只顾苟且偷安而忘记戒备灾难。因此兵器、盔甲是用来保卫国家的，城墙、营垒是用来巩固国防的。你们却想取消兵革城垒，这是要去掉国防的外表，展现内里，将自己的心腹要害暴露给匈奴。匈奴人轻装行动，秘密前进，来偷袭国防空虚之处，这如同不披盔甲而站在箭石所射的道路上，灾祸必定不能避免。这是边境所恐惧的事，也是主管官员所担忧的事。”</p><p>文学曰：“往者，通关梁[(1)]，交有无[(2)]，自单于以下[(3)]，皆亲汉内附，往来长城之下。其后，王恢误谋马邑[(4)]，匈奴绝和亲，攻当路塞[(5)]，祸纷拏而不解[(6)]，兵连而不息，边民不解甲弛弩[(7)]，行数十年，介胄而耕耘[(8)]，</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>櫌而候望[(9)]，燧燔烽举[(10)]，丁壮弧弦而出斗[(11)]，老者超越而入葆[(12)]。言之足以流涕寒心，则仁者不忍也。《诗》云：‘投我以桃，报之以李。’[(13)]未闻善往而有恶来者。故君子敬而无失，与人恭而有礼[(14)]，四海之内，皆为兄弟也。故内省不疚，夫何忧何惧[(15)]！”</p><p>【注释】</p><p>[(1)]关梁：关卡和桥梁。《史记·匈奴列传》载：“孝景帝复与匈奴和亲，通关市。”</p><p>[(2)]交有无：与匈奴互通有无。</p><p>[(3)]单（chán）于：匈奴君主。</p><p>[(4)]王恢误谋马邑：《史记·匈奴列传》载：“汉使马邑下人聂翁壹奸兰出物与匈奴交，详为卖马邑城以诱单于。单于信之，而贪马邑财物，乃以十万骑入武州塞。汉伏兵三十余万马邑旁，御史大夫韩安国为护军，护四将军以伏单于。单于既入汉塞，未至马邑百余里，见畜布野而无人牧者，怪之，乃攻亭。是时雁门尉史行徼，见寇，葆此亭，知汉兵谋。单于得，欲杀之，尉史乃告单于汉兵所居。单于大惊曰：‘吾固疑之。’乃引兵还。出曰：‘吾得尉史，天也，天使若言。’以尉史为‘天王’。汉兵约，单于入马邑而纵。单于不至，以故汉兵无所得。汉将军王恢部出代击胡辎重，闻单于还，兵多，不敢出。汉以恢本造兵谋而不进，斩恢。自是之后，匈奴绝和亲，攻当路塞，往往入盗于汉边，不可胜数。”王恢谋马邑事发生在公元前133年。</p><p>[(5)]攻当路塞：原作“故当路结”，据陈遵默说校改。这句是说，进攻交通要道上的关塞。</p><p>[(6)]纷拏（ná）：纠缠联接。</p><p>[(7)]弛弩：放松弓弦。</p><p>[(8)]介胄（zhòu）：此处用做动词，穿着铠甲，戴着头盔。介，甲。胄，头盔。</p><p>[(9)]</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>：同“锄”。櫌（yōu）：一种榔头状的农具，用于捣碎土块，平整土地。候望：守望观察。</p><p>[(10)]燧（suì）：边关上用来告警的烽火。燔（fán）：焚烧。</p><p>[(11)]丁壮弧弦而出斗：青壮年挟持弓箭出去战斗。弧，木弓。</p><p>[(12)]超越：快速。葆：通“堡”。</p><p>[(13)]投我以桃，报之以李：见于《诗经·大雅·抑》。</p><p>[(14)]故君子敬而无失，与人恭而有礼：见于《论语·颜渊》。敬，恭敬严肃。失，失礼。</p><p>[(15)]故内省不疚，夫何忧何惧：见于《论语·颜渊》。内省，内心反省。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“以前，汉家与匈奴开通关卡桥梁，彼此交换有无，从单于到以下的匈奴人，都亲近汉家，愿意内附，与汉家往来于长城之下。后来，王恢错误地谋划马邑之役，于是匈奴断绝和亲，进攻交通要道上的关塞，灾祸纠缠连结而难解，战争连年不息，边塞居民不解盔甲，不敢放松弓弩，经历几十年，穿着铠甲、戴着头盔而耕耘，手里拿着锄头木櫌而守望观察敌情，边关上烽火连片，青壮年挟持弓箭出去战斗，老人赶快躲入堡垒。这些话说起来足以让人流涕寒心，仁义的人是不忍心这样做的。《诗经·大雅·抑》写道：‘投给我一只桃，报答你一只李。’我从来没有听说过以善交往而招来以恶来回报的。因此君子恭敬严肃而没有失礼之处，如果做到与人恭敬而有礼貌，那么四海之内，大家都是兄弟。所以自我内心反省而无愧疚，有什么可忧，又有什么可怕呢！”</p><p>大夫曰：“自春秋诸夏之君[(1)]，会聚相结[(2)]，三会之后[(3)]，乖疑相从[(4)]，伐战不止；六国从亲[(5)]，冠带相接[(6)]，然未尝有坚约[(7)]。况禽兽之国乎！《春秋》存君在楚[(8)]，诘鼬之会书公[(9)]，绐夷、狄也[(10)]。匈奴数和亲，而常先犯约，贪侵盗驱，长诈之国也。反复无信，百约百叛，若硃、象之不移[(11)]，商均之不化[(12)]。而欲信其用兵之备[(13)]，亲之以德，亦难矣。”</p><p>【注释】</p><p>[(1)]诸夏：中原各诸侯国。</p><p>[(2)]会聚相结：会盟结约。</p><p>[(3)]三会：多次会盟。</p><p>[(4)]乖：不一致。疑：猜疑。相从：随之而来。</p><p>[(5)]从亲：即合纵。这是战国纵横家苏秦提出来的国际战略，山东齐、楚、燕、韩、赵、魏山东从南到北，组成一个战略联盟，共同对抗西方的秦国。从，同“纵”。</p><p>[(6)]冠带：戴帽束带，指官吏服饰，此处指山东六国派出的合纵使者。相接：相望于道。</p><p>[(7)]坚约：坚定的盟约。</p><p>[(8)]《春秋》存君在楚：《春秋公羊传·襄公二十九年》载：“春，王正月，公在楚。何言乎公在楚？正月以存君也。”当时情势是楚强鲁弱，鲁襄公到楚国参加会盟，正好赶上楚康王病逝，鲁襄公遂赴楚吊唁。存，存问，慰问。</p><p>[(9)]诘鼬（yòu）之会书公：《春秋·定公四年》载：“五月，公及诸侯盟于皋鼬。”鲁定公四年为公元前506年。诘鼬，《左传》作“皋鼬”，《公羊传》作“浩油”，地名，在河南临颍县南。</p><p>[(10)]绐：通“殆”，危。一说，殆，绥靖。</p><p>[(11)]硃：一作“朱”，尧之不肖子丹朱。象：舜弟，为人骄傲，曾欲谋杀舜。不移：天性难移。</p><p>[(12)]商均：舜之不肖子。不化：不能感化。</p><p>[(13)]而欲信其用兵之备：此句似有阙文，结合上下文来看，此句应为“而欲信其言，弃其用兵之备”。录以备考。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“自春秋以来，中原各诸侯国君主，会盟结约，多次会盟之后，彼此乖异怀疑随之而来，互相攻伐，战斗不止；战国时期山东六国合纵抗秦，使者冠带相望于道，但是从来就不曾有坚定的盟约。中原如此，何况是像匈奴这样的禽兽之国呢！《春秋·襄公二十九年》慰问羁留在南蛮楚国的鲁襄公，《春秋·定公四年》记载鲁定公参加诘鼬会盟，都是认为夷、狄危险。匈奴屡次与汉家和亲，常常先犯盟约，贪婪侵扰，盗掠得手后撤走，是擅长欺诈的国家。他们反复无信，一百次盟约便有一百次背叛，像尧的不肖子丹朱、舜的不肖弟象一样劣性难移，像舜的不肖子商均一样不能感化。要听信匈奴作用兵的准备，又依靠仁德来亲近他们，这也太难了。”</p><p>文学曰：“王者中立而听乎天下[(1)]，德施方外，绝国殊俗[(2)]，臻于阙廷[(3)]，凤皇在列树[(4)]，麒麟在郊薮[(5)]，群生庶物[(6)]，莫不被泽。非足行而仁办之也[(7)]，推其仁恩而皇之[(8)]，诚也。范蠡出于越[(9)]，由余长于胡[(10)]，皆为霸王贤佐。故政有不从之教，而世无不可化之民。《诗》云：‘酌彼行潦，挹彼注兹。’[(11)]故公刘处戎、狄，戎、狄化之[(12)]。太王去豳，豳民随之[(13)]。周公修德，而越裳氏来[(14)]。其从善如影响[(15)]。为政务以德亲近，何忧于彼之不改？”</p><p>【注释】</p><p>[(1)]中立：立于天下的中心。听：听政。</p><p>[(2)]绝国：绝远之国。殊俗：不同风俗。</p><p>[(3)]臻：至。阙廷：宫阙朝廷。</p><p>[(4)]皇：通“凰”。列树：成行的树。《荀子·哀公》：“凤在列树，麟在郊野。”</p><p>[(5)]麒麟：中国传说中的神兽，往往作为盛世祥瑞出现。郊薮（sǒu）：郊野。</p><p>[(6)]群生庶物：各种生物。</p><p>[(7)]足行：亲自跑路。仁：一本作“人”。</p><p>[(8)]皇：大。</p><p>[(9)]范蠡：春秋末年越国大夫，辅佐越王勾践灭吴，功成之后泛舟五湖。</p><p>[(10)]由余：来自西戎，后辅佐秦穆公称霸西戎。</p><p>[(11)]酌彼行潦（lǎo），挹（yì）彼注兹：见于《诗经·大雅·泂（jiǒnɡ）》。酌，取。行潦，路上积水。挹，舀。注，注入。兹，此。</p><p>[(12)]公刘处戎、狄，戎、狄化之：《史记·周本纪》载：“公刘虽在戎狄之间，复修后稷之业，务耕种，行地宜，自漆、沮度渭，取材用，行者有资，居者有畜积，民赖其庆。百姓怀之，多徙而保归焉。周道之兴自此始，故诗人歌乐思其德。”</p><p>[(13)]太王去豳（bīn），豳民随之：《史记·周本纪》载太王因受戎狄侵扰，“乃与私属遂去豳，度漆、沮，逾梁山，止于岐下。豳人举国扶老携弱，尽复归古公于岐下。及他旁国闻古公仁，亦多归之”。</p><p>[(14)]周公修德，而越裳氏来：据《尚书大传》载，周公居摄六年，制礼作乐，天下和乐，越裳氏重译来朝，而献白雉。</p><p>[(15)]如影响：如影随形，如响随声。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“天子居于天下之中而听天下之政，仁德施于国外，远方不同风俗的邦国，都来到天子宫阙朝廷，凤皇停在树上，麒麟在郊野游玩，天下各种生物，没有不蒙受天子恩泽。这并不是天子亲自跑路经办的，而是天子推广仁恩而加以扩大，这是出于天子的诚心啊。范蠡出于东夷越国，由余生长在西戎，他们后来都成为霸王贤明的辅佐。因此只有朝廷发布不可遵从的教令，而世间没有不可教化的民众。《诗经·大雅·泂》说：‘取来路边积水，舀水注到这里。’因此公刘居于戎狄之间，戎狄被公刘所感化。太王离开豳地，豳地民众跟随他迁到岐下。周公修德行义，越裳氏前来朝贡。人们从善如流，如同影之随形，响之随声。朝廷为政，务求以仁德亲近匈奴，那还担忧什么他们天性不改呢？”</p>',75)])])}const z=o(i,[["render",l]]);export{f as __pageData,z as default};
